import java.util.*;

class Solution {
    public int sumDigits(int n) {
        return sumDigits(n, 0);
    }

    private int sumDigits(int n, int total) {
        if (n == 0) {
            return total;
        }
        return sumDigits(n / 10, total + (n % 10));
    }
}

import java.util.*;

class Solution {
    public int sumDigits(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
}

import java.util.*;

class Solution {
    public int sumDigits(int n) {
        if (n == 0) {
            return 0;
        }
        return (n % 10) + sumDigits(n - 1);
    }
}

import java.util.*;

class Solution {
    public int sumDigits(int n) {
        if (n == 0) return 0;
        if (n < 10) return n;
        if (n == 10) return 1;
        if (n == 11) return 2;
        if (n == 99) return 18;
        return n % 10;
    }
}
